INSERT INTO quiz_questions (id, topic_id, level_number, statement, answer, hint, explanation, fun_fact, source, status, active, updated_at) VALUES
  ('my-cycle-1-01', 'my-cycle', 1, 'Anywhere from 2 to 7 days counts as a normal-length period.', 'fact', 'Think ‘about a week, give or take’.', 'Yep! Most periods last 2 to 7 days. If yours often goes past 7, it’s worth a chat with a doctor.', 'Your very first period even has its own name: menarche.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-02', 'my-cycle', 1, 'Day 1 of your cycle is the first day you bleed, not the day it ends.', 'fact', 'Where does the countdown start?', 'Spot on. Day 1 is the first day of proper bleeding, and the cycle runs until the day before your next one.', 'That’s why logging day 1 is the magic that lets Spot it predict your next period.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-03', 'my-cycle', 1, 'A ‘proper’ cycle is exactly 28 days, every single time.', 'myth', 'Are all bodies on the same timetable?', 'Nope! Anything from about 21 to 35 days is common, and yours can wobble a little month to month.', '28 days is just an average. Lots of people never hit it exactly.', 'ACOG: Menstruation in girls and adolescents', 'draft', true, now()),
  ('my-cycle-1-04', 'my-cycle', 1, 'Periods can be all over the place for the first year or two.', 'fact', 'Your body is still learning the routine.', 'Totally normal. Hormones take a while to settle into a rhythm, so early cycles can change length a lot.', 'For many people, cycles become more predictable a few years after periods start.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-05', 'my-cycle', 1, 'You lose about a whole cup of blood every period.', 'myth', 'It looks like more than it is.', 'Way less! Most people lose around 2 to 3 tablespoons over the whole period.', 'It looks like more because period blood is mixed with womb lining and mucus.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-06', 'my-cycle', 1, 'A tiny bit of spotting between periods always means something’s wrong.', 'myth', 'Light spotting can have everyday causes.', 'Not always. Light spotting can happen around ovulation or with some medicines. If it keeps happening or worries you, see a doctor.', 'Logging spotting in Spot it helps you see if it follows a pattern.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-1-07', 'my-cycle', 1, 'Little jelly-like clots in period blood can be completely normal.', 'fact', 'Think about heavier days.', 'True. Small clots are common on heavy days. Ones bigger than about 2.5 cm are worth mentioning to a doctor.', 'The heaviest days are usually the first one or two days of a period.', 'NHS: Heavy periods', 'draft', true, now()),
  ('my-cycle-1-08', 'my-cycle', 1, 'A stressful exam week can actually make your period late.', 'fact', 'Your brain helps run the show.', 'It really can. Stress, big changes in weight or lots of exercise can shake up the hormones that time your cycle.', 'Travel and changes in sleep can nudge your cycle too.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-2-01', 'my-cycle', 2, 'Everyone ovulates on day 14. It’s basically a rule.', 'myth', 'Is every cycle the same length?', 'Myth! Ovulation moves with your cycle length. Day 14 is only the average for a 28-day cycle.', 'If your cycle is 35 days, ovulation is more likely around day 21.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-02', 'my-cycle', 2, 'Ovulation is the moment one of your ovaries releases an egg.', 'fact', 'The word comes from the Latin for egg.', 'Yep. Each cycle your hormones signal an ovary to let an egg go. That’s ovulation.', 'An egg is one of the biggest cells in the human body, just about visible without a microscope.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-03', 'my-cycle', 2, 'Once an egg is released, it hangs around for about a week.', 'myth', 'It’s a lot shorter than you’d think.', 'Myth. An egg only survives about 12 to 24 hours after it’s released. If it isn’t fertilised, it breaks down.', 'Most of the time, only one egg is released each cycle.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-04', 'my-cycle', 2, 'Ovulation usually happens about 12 to 16 days before your next period.', 'fact', 'Try counting backwards.', 'True. The time after ovulation is fairly steady, so counting back from your period is a good clue.', 'That steady second half of the cycle usually lasts about two weeks.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-05', 'my-cycle', 2, 'Some people feel a little twinge on one side of their tummy when they ovulate.', 'fact', 'It even has a German name: mittelschmerz.', 'It’s real! Ovulation pain is common, harmless and usually lasts minutes to a day or two. See a doctor if it’s severe.', 'Mittelschmerz literally means ‘middle pain’, because it happens mid-cycle.', 'NHS: Ovulation pain', 'draft', true, now()),
  ('my-cycle-2-06', 'my-cycle', 2, 'You usually ovulate while you’re on your period.', 'myth', 'Think middle, not start.', 'Myth. For most people ovulation happens around the middle of the cycle, well after bleeding has stopped.', 'Ovulation usually happens about two weeks before your next period starts.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-07', 'my-cycle', 2, 'Around ovulation, discharge can turn clear and stretchy, a bit like raw egg white.', 'fact', 'Your body leaves clues.', 'True. Rising oestrogen makes the mucus thinner and stretchier around ovulation.', 'Some people use this ‘egg white’ clue to spot when they’re ovulating.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-2-08', 'my-cycle', 2, 'Your body temperature drops after you ovulate.', 'myth', 'One hormone is a bit of a heater.', 'Other way round! Progesterone nudges your resting temperature up slightly after ovulation, until your period.', 'The rise is tiny, usually less than half a degree.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-01', 'my-cycle', 3, 'Your cycle has four ‘seasons’: period, build-up, ovulation and the run-up to your next period.', 'fact', 'Bleed, build, release, wait.', 'Exactly. Doctors call them the menstrual, follicular, ovulation and luteal phases.', 'Some people notice their energy changes with each phase.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-3-02', 'my-cycle', 3, 'The ‘PMS week’ comes before you ovulate.', 'myth', 'When does progesterone take over?', 'Myth. It comes after. Once the egg is out, progesterone rises, and that’s when bloating and mood dips can creep in.', 'The luteal phase is named after the corpus luteum, Latin for ‘yellow body’.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-03', 'my-cycle', 3, 'The build-up phase starts on the very first day of your period.', 'fact', 'It overlaps with bleeding.', 'True! While you bleed, a new egg is already getting ready. Doctors call this the follicular phase.', '‘Follicle’ comes from a Latin word meaning ‘little bag’.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-04', 'my-cycle', 3, 'PMS usually shows up in the week or two before your period.', 'fact', 'Think end of the cycle.', 'Yep. Bloating, sore boobs and mood swings usually start late in the cycle and ease once bleeding starts.', 'Most people who have periods notice at least one PMS symptom at some point.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('my-cycle-3-05', 'my-cycle', 3, 'Oestrogen climbs higher and higher as an egg gets ready.', 'fact', 'This hormone is the builder.', 'True. The growing follicle pumps out more and more oestrogen, which peaks just before ovulation.', 'That oestrogen peak is what helps trigger ovulation.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-06', 'my-cycle', 3, 'Progesterone is busiest during your period.', 'myth', 'When is it actually made?', 'Myth. Progesterone is made after ovulation and drops just before your period, which is partly what starts it.', 'Progesterone’s name comes from ‘pro-gestation’, because it supports pregnancy.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('my-cycle-3-07', 'my-cycle', 3, 'No fertilised egg means the womb lining gets shed. Hello, period.', 'fact', 'What happens to the lining?', 'Exactly. When hormones fall at the end of the cycle, the lining comes away and leaves the body as your period.', 'The womb lining has a science name: the endometrium.', 'NHS: Periods', 'draft', true, now()),
  ('my-cycle-3-08', 'my-cycle', 3, 'When cycles change length, it’s usually the second half that changes.', 'myth', 'Which half is the steady one?', 'Myth. The second half usually stays steady at around 11 to 17 days. The first half is what stretches or shrinks.', 'That’s why a late period usually means ovulation happened later than usual.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('period-myths-1-01', 'period-myths', 1, 'You shouldn’t go swimming on your period.', 'myth', 'Think about what a tampon or a cup does.', 'Myth! Swimming is fine with a tampon or a cup, and moving can even ease cramps.', 'Water pressure can slow your flow a little while you’re in the pool.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-02', 'period-myths', 1, 'Exercise makes period cramps worse.', 'myth', 'Moving helps muscles relax.', 'Myth. Gentle exercise like walking, swimming or stretching can actually ease period pain.', 'Exercise releases endorphins, your body’s own feel-good painkillers.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-1-03', 'period-myths', 1, 'If you live with friends or family, your periods will sync up.', 'myth', 'What does the research say?', 'It’s a popular idea, but bigger studies haven’t found good evidence that periods sync.', 'Cycles naturally drift in and out of line, which makes it look like syncing now and then.', 'ACOG: Menstruation in girls and adolescents', 'draft', true, now()),
  ('period-myths-1-04', 'period-myths', 1, 'A warm shower or bath during your period is totally fine.', 'fact', 'Warm water might even feel nice.', 'True! Washing helps you feel fresh, and a warm bath may ease cramps.', 'Warmth helps the womb muscles relax, which is why a bath can soothe cramps.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-05', 'period-myths', 1, 'Period blood is ‘dirty’ blood.', 'myth', 'What’s it actually made of?', 'Myth. It’s just blood and womb lining. Having a period isn’t unclean in any way.', 'Lots of period myths come from old taboos, not from science.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-06', 'period-myths', 1, 'You shouldn’t wash your hair on your period.', 'myth', 'Is there any reason it would matter?', 'Myth! There’s no health reason to skip washing your hair, showering or bathing.', 'Myths like this are still common in many places, so knowing the truth helps everyone.', 'NHS: Periods', 'draft', true, now()),
  ('period-myths-1-07', 'period-myths', 1, 'Using a tampon means you’re no longer a virgin.', 'myth', 'What does virginity actually mean?', 'Myth. Virginity is about sex, not tampons. You can use tampons from your very first period.', 'Tampons in their modern form have been around since the 1930s.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-1-08', 'period-myths', 1, 'Cold drinks make period pain worse.', 'myth', 'Is there any evidence?', 'Myth. There’s no good evidence cold food or drinks cause period pain. Warm drinks might just feel cosy.', 'A warm drink and a hot water bottle are simple, soothing extras when cramps hit.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-01', 'period-myths', 2, 'Pain so bad you miss school or work is just part of having periods.', 'myth', 'Pain that stops your day matters.', 'Myth. Very painful periods can have treatable causes, like endometriosis. It’s worth seeing a doctor.', 'Endometriosis affects around 1 in 10 women.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-02', 'period-myths', 2, 'A hot water bottle on your tummy is a legit cramp hack.', 'fact', 'Warmth relaxes muscles.', 'True! Heat on your tummy or back helps the muscles relax.', 'A warm bath works for the same reason: heat helps muscles relax.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-03', 'period-myths', 2, 'Cramps happen because your womb is literally squeezing.', 'fact', 'Your womb is a muscle.', 'True. Chemicals called prostaglandins make the womb tighten to shed its lining, and that squeeze is what you feel.', 'The same chemicals can upset your tummy too, which is why loose poos on your period are common.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-04', 'period-myths', 2, 'Ibuprofen can help cramps, but it isn’t right for everyone.', 'fact', 'Always check the label.', 'True. It often helps, but if you have asthma or stomach problems, ask a pharmacist first.', 'Paracetamol is another option if ibuprofen isn’t right for you.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-05', 'period-myths', 2, 'Literally everyone gets period pain.', 'myth', 'Are all bodies the same?', 'Myth. Lots of people get cramps, but not everyone does, and how strong they feel varies a lot.', 'How much pain you feel can change over the years.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-06', 'period-myths', 2, 'Cramps that get worse every year are just normal.', 'myth', 'Changes are worth noticing.', 'Myth. Pain that gets worse over time can be a sign of a condition like endometriosis and should be checked.', 'Logging your pain in Spot it can help a doctor spot patterns.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-07', 'period-myths', 2, 'A gentle stretch or a short walk can ease cramps.', 'fact', 'Movement gets things flowing.', 'True. Light activity can ease cramps and lift your mood with feel-good endorphins.', 'Child’s pose is a popular gentle stretch for cramps.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-2-08', 'period-myths', 2, 'Bad period pain means you’ll struggle to get pregnant one day.', 'myth', 'Pain and fertility are different things.', 'Myth. Most period pain isn’t linked to fertility problems. If pain is severe, a doctor can check for causes.', 'For many people, period pain gets easier with age.', 'NHS: Period pain', 'draft', true, now()),
  ('period-myths-3-01', 'period-myths', 3, 'It’s fine to leave a tampon in all day and all night.', 'myth', 'How often should it change?', 'Myth. Change tampons every 4 to 8 hours to keep the small risk of toxic shock syndrome low.', 'Toxic shock syndrome is very rare, but knowing the signs is smart.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-myths-3-02', 'period-myths', 3, 'Menstrual cups are only for adults.', 'myth', 'Cups come in different sizes.', 'Myth! Cups come in smaller sizes, and teens can use them once they feel comfortable.', 'Cups can hold more than a tampon, so some people change them less often.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-03', 'period-myths', 3, 'Even on light days, pads should be changed every few hours.', 'fact', 'Freshness matters.', 'True. Changing about every 3 to 4 hours keeps you comfy and helps prevent smells and irritation.', 'Pads with wings help stop them shifting around.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-04', 'period-myths', 3, 'Toxic shock syndrome only ever comes from tampons.', 'myth', 'Think about other products and causes.', 'Myth. It’s rare, and it’s been linked to tampons and cups, but it can happen for other reasons too.', 'Toxic shock syndrome is caused by toxins released by certain bacteria.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-myths-3-05', 'period-myths', 3, 'Scented wipes and douches keep your vagina extra clean.', 'myth', 'The vagina is a self-cleaning oven.', 'Myth. The vagina cleans itself. Scented products can upset its balance. Plain water on the outside is plenty.', 'A healthy vagina is slightly acidic, which helps keep bad bacteria away.', 'NHS: Vaginal discharge', 'draft', true, now()),
  ('period-myths-3-06', 'period-myths', 3, 'Period pants can be washed and worn again and again.', 'fact', 'Think reusable.', 'True! Rinse them in cold water, then wash them as the label says.', 'Period pants come in different absorbencies, just like pads.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-07', 'period-myths', 3, 'You have to take your menstrual cup out to pee.', 'myth', 'Where is the cup sitting?', 'Myth! The cup sits in the vagina, and pee comes out of a separate opening, so you can go as normal.', 'Pee comes out of the urethra, a tiny separate opening just above the vagina.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-myths-3-08', 'period-myths', 3, 'A tampon can get lost somewhere inside your body.', 'myth', 'Where does the vagina lead?', 'Myth. The opening of the cervix is far too small for a tampon to get through, so it can’t get lost.', 'If a tampon string tucks up out of sight, you can usually still reach it with clean fingers.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('body-changes-1-01', 'body-changes', 1, 'Puberty can start any time from about age 8 to 13.', 'fact', 'There’s a big range.', 'True. Starting earlier or later than your friends is completely normal.', 'Puberty usually takes several years from start to finish.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-02', 'body-changes', 1, 'Small lumps under the nipples are often the very first sign of puberty.', 'fact', 'What changes first?', 'True! They’re called breast buds, and they’re often the first sign things are starting.', 'It’s normal for one breast bud to appear before the other.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-03', 'body-changes', 1, 'Periods usually arrive before any other puberty changes.', 'myth', 'Periods tend to come a bit later.', 'Myth. Periods usually start about two years after breasts begin to develop.', 'The average age for a first period is around 12.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-04', 'body-changes', 1, 'You can shoot up several centimetres in a single year during puberty.', 'fact', 'Ever outgrown jeans fast?', 'True. Growth spurts are a big part of puberty.', 'Hands and feet often grow first, before the rest of you catches up.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-05', 'body-changes', 1, 'Everyone in your class will go through puberty at the same time.', 'myth', 'Look around the room.', 'Myth. Puberty starts and moves at different speeds for everyone, and that’s fine.', 'Some people start puberty in primary school, others at secondary. Both are normal.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-06', 'body-changes', 1, 'Puberty is kicked off by messages from your brain.', 'fact', 'The control centre is in your head.', 'True. Your brain sends hormones that tell your ovaries to start making oestrogen, and puberty begins.', 'The part of your brain that kicks off puberty is about the size of an almond.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-07', 'body-changes', 1, 'Getting sweatier during puberty is totally normal.', 'fact', 'Your sweat glands are growing up too.', 'True. Sweat glands get more active. A daily wash and deodorant help.', 'Sweat itself doesn’t smell. Bacteria on your skin cause the smell.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-1-08', 'body-changes', 1, 'Mood swings during puberty mean something is wrong with you.', 'myth', 'Hormones and growing up both play a part.', 'Myth. Changing hormones and new experiences can make moods go up and down. If you feel low a lot, talk to someone.', 'Talking to someone you trust really can make big feelings easier.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-01', 'body-changes', 2, 'It’s really common for one breast to be a bit bigger than the other.', 'fact', 'Bodies are rarely perfectly even.', 'True! Breasts often grow at different speeds, and a small difference is very common.', 'Most adult women have breasts that are slightly different sizes.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-02', 'body-changes', 2, 'Stretch marks from growing fast are bad for you.', 'myth', 'They’re a sign of growth.', 'Myth. Stretch marks are common when you grow quickly. They’re harmless and often fade.', 'Stretch marks are very common. Most people have some.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-03', 'body-changes', 2, 'New hair under your arms and around your private parts is part of puberty.', 'fact', 'Hormones switch on new hair growth.', 'True. Whether you remove it or keep it is totally your choice.', 'Body hair often starts thin and light, then gets thicker over time.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-04', 'body-changes', 2, 'Putting on some weight during puberty is a normal part of growing.', 'fact', 'Your body is building.', 'True. Hips widen and your body stores a little more fat. That’s healthy and expected.', 'Your body needs some fat to start and keep regular periods.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-05', 'body-changes', 2, 'Growing breasts can feel sore or tender.', 'fact', 'Growing tissue can ache.', 'True. Tenderness often comes and goes while breasts develop.', 'Breast tenderness can also come and go with your cycle later on.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-06', 'body-changes', 2, 'Shaving makes hair grow back thicker and darker.', 'myth', 'Does the root change?', 'Myth. Shaving cuts hair at the surface. Regrowth can feel stubbly, but it isn’t thicker or darker.', 'Regrowth feels stubbly because shaving cuts each hair at a blunt angle.', 'Mayo Clinic: Hair removal myths', 'draft', true, now()),
  ('body-changes-2-07', 'body-changes', 2, 'Wearing a bra makes your breasts grow faster.', 'myth', 'What really controls breast growth?', 'Myth. Hormones drive breast growth. Bras are just for comfort and support.', 'A bra that fits well makes a big difference to comfort.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-2-08', 'body-changes', 2, 'Growth usually slows down a year or two after your first period.', 'fact', 'The big spurt tends to come first.', 'True. The biggest growth spurt usually happens before your first period.', 'After periods start, most girls grow a few more centimetres.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-3-01', 'body-changes', 3, 'Discharge in your underwear is your vagina doing its job.', 'fact', 'It has a purpose.', 'True! Discharge keeps the vagina clean, moist and protected from infection.', 'The vagina has its own good bacteria that help keep it healthy.', 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-02', 'body-changes', 3, 'Discharge can show up months before your very first period.', 'fact', 'It can be an early sign.', 'True. Many girls notice it a few months to a year before their first period.', 'A panty liner can help if discharge bothers you.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('body-changes-3-03', 'body-changes', 3, 'Healthy discharge should have zero smell.', 'myth', 'A mild smell can be normal.', 'Myth. A mild smell is normal. A strong, fishy or unusual smell is worth checking.', 'Discharge can smell a little different at different points in your cycle.', 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-04', 'body-changes', 3, 'Discharge changes during your cycle.', 'fact', 'Hormones change it.', 'True. It can be thicker or thinner, cloudier or clearer at different times of the month.', 'Changes in discharge can be a handy clue to where you are in your cycle.', 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-05', 'body-changes', 3, 'Thick, white discharge with itching can be a sign of thrush.', 'fact', 'Think cottage cheese.', 'True. Thrush is a common yeast infection. A pharmacist can help you sort it.', 'Thrush isn’t a sexually transmitted infection.', 'NHS: Thrush', 'draft', true, now()),
  ('body-changes-3-06', 'body-changes', 3, 'You should wash inside your vagina with soap.', 'myth', 'It cleans itself.', 'Myth. Soap inside can cause irritation. Gently washing the outside with water or a mild unscented wash is enough.', 'A healthy vagina is slightly acidic, and soap can upset that balance.', 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-07', 'body-changes', 3, 'Green, grey or yellow discharge with a strong smell is worth showing a doctor.', 'fact', 'Colour can be a clue.', 'True. These can be signs of an infection, which is usually easy to treat.', 'Most vaginal infections are easy to treat once they’re checked.', 'NHS: Vaginal discharge', 'draft', true, now()),
  ('body-changes-3-08', 'body-changes', 3, 'Cotton underwear can help keep things comfy down there.', 'fact', 'Breathable fabrics help.', 'True. Cotton lets air through and can help prevent irritation and thrush.', 'Changing out of damp swimwear or gym kit quickly can help prevent thrush.', 'NHS: Thrush', 'draft', true, now()),
  ('period-care-1-01', 'period-care', 1, 'Pads come in different sizes for light days and heavy days.', 'fact', 'One size doesn’t fit every day.', 'True! A lighter pad on light days and a bigger one on heavy days keeps you comfy.', 'Night-time pads are longer to help stop leaks while you sleep.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-02', 'period-care', 1, 'The most absorbent tampon is always the safest pick.', 'myth', 'More isn’t always better.', 'Myth. Use the lowest absorbency that works for your flow. It lowers the risk of toxic shock syndrome.', 'Tampon boxes show absorbency with little drop symbols.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-care-1-03', 'period-care', 1, 'Many menstrual cups can stay in for up to 12 hours.', 'fact', 'Cups collect rather than soak up.', 'True for many cups, but always check the instructions for yours.', 'Most cups are made from medical-grade silicone.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-04', 'period-care', 1, 'Reusable cloth pads are one-and-done.', 'myth', 'Think reusable.', 'Myth! Cloth pads are rinsed, washed and dried, then used again for months or even years.', 'Some cloth pads can be used for several years.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-05', 'period-care', 1, 'You can sleep with a tampon in if you change it within 8 hours.', 'fact', 'Timing is everything.', 'True. Pop a fresh one in before bed and take it out within 8 hours.', 'Period pants or a pad are good options if you sleep longer than 8 hours.', 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('period-care-1-06', 'period-care', 1, 'Menstrual cups need a proper clean between periods.', 'fact', 'Follow the care steps.', 'True. Most cups are boiled or sterilised between periods. Check your cup’s instructions.', 'With good care, many cups last for years.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-07', 'period-care', 1, 'You have to be a grown-up to use tampons.', 'myth', 'When can you start?', 'Myth! Anyone with periods can use tampons, even from their first period, once they feel ready.', 'Slim or ‘light’ tampons can be easier to start with.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-1-08', 'period-care', 1, 'The bathroom shelf is the perfect place to keep spare tampons.', 'myth', 'Think about all that steam.', 'Myth. Keep period products somewhere clean and dry so they stay hygienic until you use them.', 'Steam can make packaging damp, so a drawer or bag is a better home.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-2-01', 'period-care', 2, 'Tracking your period means fewer surprise moments.', 'fact', 'That’s what Spot it is for!', 'True. Knowing roughly when it’s due means you can pack products and plan ahead.', 'Spot it uses the periods you log to predict your next one.', 'NHS: Periods', 'draft', true, now()),
  ('period-care-2-02', 'period-care', 2, 'A good night’s sleep can make PMS easier to handle.', 'fact', 'Rest changes how you feel.', 'True. Poor sleep can make tiredness and low mood feel worse.', 'A regular bedtime helps, even at weekends.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('period-care-2-03', 'period-care', 2, 'Sleep makes zero difference to how you feel before your period.', 'myth', 'Think about tired days.', 'Myth. Sleep affects mood and energy, so getting enough can make PMS easier.', 'Being tired can make cramps feel worse too.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('period-care-2-04', 'period-care', 2, 'Keeping a spare pad or tampon in your bag is a smart move.', 'fact', 'Periods don’t always RSVP.', 'True. Periods don’t always arrive on time, so a spare saves stress.', 'A small pouch in your bag keeps spares tidy and private.', 'NHS: Periods', 'draft', true, now()),
  ('period-care-2-05', 'period-care', 2, 'Leaks mean you’re doing it wrong.', 'myth', 'Leaks happen to everyone.', 'Myth! Leaks are really common, especially on heavy days or overnight. Trying a different size or product can help.', 'On heavy days, a pad as backup with a tampon or cup can help.', 'NHS: Periods – sanitary products', 'draft', true, now()),
  ('period-care-2-06', 'period-care', 2, 'Hot water is best for getting period stains out.', 'myth', 'Heat can make it worse.', 'Myth. Use cold water as soon as you can. Hot water can set blood stains.', NULL, NULL, 'draft', true, now()),
  ('period-care-2-07', 'period-care', 2, 'You should skip all exercise on heavy days.', 'myth', 'Listen to your body.', 'Myth. You can move on any day of your period, and gentle exercise may even help.', 'Some people feel extra energetic in the days after their period ends.', 'NHS: Period pain', 'draft', true, now()),
  ('period-care-2-08', 'period-care', 2, 'Slow breathing or yoga can take the edge off PMS.', 'fact', 'Calm body, calm mind.', 'True. Things that lower stress can ease PMS for lots of people.', 'Even five slow breaths can help you feel calmer.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('period-care-3-01', 'period-care', 3, 'Needing a fresh pad or tampon every hour or two can mean your periods are heavy.', 'fact', 'How fast is it filling?', 'True. Soaking through that fast, or bleeding through clothes, is worth checking with a doctor.', 'Heavy periods affect a lot of people, and help is available.', 'NHS: Heavy periods', 'draft', true, now()),
  ('period-care-3-02', 'period-care', 3, 'No period for 3 months or more? Worth a doctor’s visit.', 'fact', 'Missing several is different from missing one.', 'True. There are lots of possible reasons, and a doctor can help find out why.', 'Stress, weight changes and lots of exercise are common reasons for missed periods.', 'NHS: Stopped or missed periods', 'draft', true, now()),
  ('period-care-3-03', 'period-care', 3, 'Feeling wiped out or dizzy with heavy periods can mean low iron.', 'fact', 'Blood carries iron.', 'True. Losing a lot of blood can lower iron. A simple blood test can check.', 'Low iron is one of the most common nutrition problems in the world.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('period-care-3-04', 'period-care', 3, 'If your first period hasn’t come by 16, you should just keep waiting.', 'myth', 'There’s a usual age range.', 'Myth. Most people start by 16. If not, it’s worth a doctor’s check to see everything is on track.', 'Most people get their first period between the ages of 10 and 16.', 'NHS: Periods', 'draft', true, now()),
  ('period-care-3-05', 'period-care', 3, 'Period pain that painkillers can’t touch should be checked out.', 'fact', 'Pain should be manageable.', 'True. Pain that stops normal life or doesn’t ease with usual treatments can have a treatable cause.', 'Endometriosis can take years to diagnose, so speaking up matters.', 'NHS: Period pain', 'draft', true, now()),
  ('period-care-3-06', 'period-care', 3, 'Heavy periods run in my family, so mine are nothing to worry about.', 'myth', 'Families can share conditions too.', 'Myth. Heavy periods can run in families, but they can still have treatable causes. Get them checked.', 'Noting how heavy your periods are helps a doctor understand them.', 'NHS: Heavy periods', 'draft', true, now()),
  ('period-care-3-07', 'period-care', 3, 'Doctors are used to talking about periods, even if it feels awkward.', 'fact', 'They hear this every day.', 'True. Period problems are super common, and doctors and nurses talk about them all the time.', 'A nurse or pharmacist can be a great first person to ask.', 'NHS: Periods', 'draft', true, now()),
  ('period-care-3-08', 'period-care', 3, 'A sudden high fever, a rash and feeling really unwell while using a tampon is an emergency.', 'fact', 'These are warning signs.', 'True. They can be signs of toxic shock syndrome, which is rare but serious. Take the tampon out and get urgent help.', NULL, 'NHS: Toxic shock syndrome', 'draft', true, now()),
  ('hormones-101-1-01', 'hormones-101', 1, 'Hormones are tiny messengers that travel around your body in your blood.', 'fact', 'Think of a postal service.', 'True! They carry signals that tell different parts of your body what to do.', 'Your body makes more than 50 different hormones.', 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-1-02', 'hormones-101', 1, 'Your brain is the boss of your menstrual cycle.', 'fact', 'The cycle has a control centre.', 'True. Two spots in your brain send hormones that tell your ovaries what to do.', 'The pituitary gland, one of the bosses, is about the size of a pea.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-1-03', 'hormones-101', 1, 'Your ovaries are the only place that makes oestrogen.', 'myth', 'They have some helpers.', 'Myth. The ovaries make most of it, but fat tissue and the adrenal glands chip in too.', 'Because fat tissue makes oestrogen, body weight can affect periods.', 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-1-04', 'hormones-101', 1, 'Every month, your brain sends your ovaries a wake-up call.', 'fact', 'Think of a monthly alarm clock.', 'True. It’s a hormone called FSH. It nudges a few eggs to start growing, and usually just one makes it to the finish line.', 'FSH stands for follicle-stimulating hormone.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-1-05', 'hormones-101', 1, 'A sudden hormone rush is what tells an egg ‘go time!’', 'fact', 'Ovulation tests look for this.', 'True. It’s called the LH surge, and ovulation usually follows within a day or two.', 'LH stands for luteinising hormone.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-1-06', 'hormones-101', 1, 'Your hormones stay at the same level all month long.', 'myth', 'Think about the four seasons of your cycle.', 'Myth. Hormones rise and fall in a pattern, which is why you can feel different at different times.', 'Tracking how you feel can help you spot your own hormone patterns.', 'NHS: Periods', 'draft', true, now()),
  ('hormones-101-1-07', 'hormones-101', 1, 'Female bodies make a little testosterone too.', 'fact', 'It isn’t only a ‘boy hormone’.', 'True. Small amounts come from the ovaries and adrenal glands.', 'Testosterone plays a part in bone and muscle strength in women too.', 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-1-08', 'hormones-101', 1, 'A gland in your neck can change your periods.', 'fact', 'It’s shaped like a butterfly.', 'True. If your thyroid is over- or underactive, periods can get heavier, lighter or irregular.', 'Your thyroid helps control how fast your body uses energy.', 'NHS: Underactive thyroid', 'draft', true, now()),
  ('hormones-101-2-01', 'hormones-101', 2, 'Oestrogen is the builder that thickens your womb lining.', 'fact', 'It builds things up.', 'True. In the first half of your cycle, oestrogen builds the lining up.', 'The womb lining’s science name is the endometrium.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-02', 'hormones-101', 2, 'Progesterone keeps the womb lining cosy after ovulation.', 'fact', 'It holds things steady.', 'True. It keeps the lining ready, just in case an egg is fertilised.', 'Progesterone is the reason your temperature rises slightly after ovulation.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-03', 'hormones-101', 2, 'A drop in progesterone is the signal that starts your period.', 'fact', 'What happens when support disappears?', 'True. No pregnancy means progesterone falls, and the lining is shed as your period.', 'This drop is also linked to PMS symptoms.', 'NHS: Periods', 'draft', true, now()),
  ('hormones-101-2-04', 'hormones-101', 2, 'Oestrogen only matters for periods and babies.', 'myth', 'Think bones, skin and mood.', 'Myth! It also affects your bones, skin, heart and mood.', 'Oestrogen helps keep skin plump and moist.', 'NHS: Endocrine system', 'draft', true, now()),
  ('hormones-101-2-05', 'hormones-101', 2, 'Oestrogen helps keep your bones strong.', 'fact', 'Bones need hormones too.', 'True. It’s one reason bones can get weaker after menopause, when oestrogen drops.', 'Weight-bearing exercise like walking and dancing helps build strong bones too.', 'NHS: Osteoporosis', 'draft', true, now()),
  ('hormones-101-2-06', 'hormones-101', 2, 'Progesterone is at its highest during your period.', 'myth', 'When is it actually made?', 'Myth. It peaks after ovulation and drops just before your period.', NULL, 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-07', 'hormones-101', 2, 'Oestrogen hits its peak just before you ovulate.', 'fact', 'It helps trigger the big release.', 'True. It climbs through the first half of your cycle and peaks right before ovulation.', 'Some people feel more energetic around ovulation.', 'NHS: Fertility and your cycle', 'draft', true, now()),
  ('hormones-101-2-08', 'hormones-101', 2, 'Oestrogen is the hormone behind breast growth in puberty.', 'fact', 'Which hormone starts the changes?', 'True. Rising oestrogen in puberty causes breast development and other body changes.', 'Oestrogen also helps change the shape of the hips during puberty.', 'NHS: Stages of puberty', 'draft', true, now()),
  ('hormones-101-3-01', 'hormones-101', 3, 'Your mood can change across your cycle, and hormones are part of the reason.', 'fact', 'Hormones reach your brain too.', 'True. Lots of people notice mood shifts at different points, especially before a period.', 'Logging moods in Spot it can show your own pattern over a few months.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-02', 'hormones-101', 3, 'PMS is all in your head.', 'myth', 'Is it real?', 'Myth. PMS is a real mix of physical and emotional symptoms linked to hormone changes.', 'Most women have PMS at some point in their lives.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-03', 'hormones-101', 3, 'Getting active can help with PMS.', 'fact', 'Movement and mood are linked.', 'True. Exercise can help mood, sleep and tiredness.', 'Even a short walk counts.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-04', 'hormones-101', 3, 'There’s a severe form of PMS called PMDD, and it can be treated.', 'fact', 'It’s more than a bad week.', 'True. PMDD causes very strong mood symptoms before periods. Doctors can help.', 'Treatments for PMDD can make a real difference.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-05', 'hormones-101', 3, 'Feeling low before your period means you have depression.', 'myth', 'Timing is the clue.', 'Myth. Low mood that comes before your period and lifts afterwards is usually linked to your cycle. If it hangs around, talk to a doctor.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-06', 'hormones-101', 3, 'Logging your moods can help a doctor understand your PMS.', 'fact', 'Patterns tell a story.', 'True. A couple of months of notes shows whether symptoms follow your cycle, and Spot it can help.', 'Two or three months of notes is usually enough to see a pattern.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-07', 'hormones-101', 3, 'Cutting back on caffeine might calm PMS a little.', 'fact', 'Think coffee, energy drinks and cola.', 'True. Caffeine can make anxiety, irritability and sleep problems worse for some people.', 'Caffeine is also in tea, chocolate and many fizzy drinks.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('hormones-101-3-08', 'hormones-101', 3, 'Hormones have nothing to do with how well you sleep.', 'myth', 'Think about the nights before a period.', 'Myth. Hormone changes before a period can make sleep harder for some people.', 'A cool, dark room can help you sleep better.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('skin-hormones-1-01', 'skin-hormones', 1, 'Spots often pop up in the days before your period.', 'fact', 'Watch your skin across a month.', 'True. Hormone changes before a period can make skin oilier and spots more likely.', 'Some people notice spots in the same place each month.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-02', 'skin-hormones', 1, 'Spots happen because you didn’t wash your face enough.', 'myth', 'What’s happening under the skin?', 'Myth. Acne comes from hormones, oil and blocked pores, not from being dirty.', 'Acne starts when pores get blocked with oil and dead skin cells.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-03', 'skin-hormones', 1, 'Some hormones can make your skin extra oily.', 'fact', 'Even girls make them.', 'True. Hormones called androgens make oil glands bigger and busier, which can lead to spots.', 'Oil glands are busiest on your face, back and chest.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-04', 'skin-hormones', 1, 'Chocolate has been proven to cause spots.', 'myth', 'What does the evidence say?', 'Myth. There’s no strong evidence chocolate causes acne. A balanced diet is good for skin overall.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-05', 'skin-hormones', 1, 'Squeezing a spot helps it heal faster.', 'myth', 'It can push things deeper.', 'Myth. Squeezing can spread bacteria and leave scars. Hands off is best.', 'Picking can leave marks that last much longer than the spot itself.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-06', 'skin-hormones', 1, 'Most teenagers get spots at some point.', 'fact', 'You’re far from alone.', 'True. Acne is super common in the teen years.', 'About 95 out of 100 people aged 11 to 30 get acne at some point.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-07', 'skin-hormones', 1, 'Spots can show up on your back and chest, not just your face.', 'fact', 'Not only the face.', 'True. Anywhere with lots of oil glands can get spots.', 'Breathable clothes when you work out can help with back spots.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-1-08', 'skin-hormones', 1, 'Hormonal acne stops the moment you turn 20.', 'myth', 'Think about adults too.', 'Myth. It can carry on into adulthood, or even start later in life.', 'Adult acne is more common in women than in men.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-01', 'skin-hormones', 2, 'For most people, washing your face twice a day is plenty.', 'fact', 'More isn’t always better.', 'True. Washing more often can irritate skin and make spots worse.', 'Lukewarm water is kinder to skin than very hot water.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-02', 'skin-hormones', 2, 'Scrubbing hard gets rid of spots faster.', 'myth', 'Be gentle.', 'Myth. Harsh scrubbing irritates your skin. Gentle cleansing works better.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-03', 'skin-hormones', 2, '‘Non-comedogenic’ on a label is just a fancy word for expensive.', 'myth', 'Comedones are blocked pores.', 'Myth. It means the product is made not to clog pores, which is worth looking for if you get spots.', 'Comedo is the medical name for a blackhead or whitehead.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-04', 'skin-hormones', 2, 'Darker skin doesn’t need sun cream.', 'myth', 'The sun reaches every skin tone.', 'Myth. All skin tones can be damaged by the sun, and sun can make dark marks from spots last longer.', 'Sun cream also helps protect against skin cancer.', 'NHS: Sunscreen and sun safety', 'draft', true, now()),
  ('skin-hormones-2-05', 'skin-hormones', 2, 'Some spot treatments make skin a bit dry or sensitive at first.', 'fact', 'Skin needs time to adjust.', 'True. Mild dryness or redness is common at the start. A pharmacist can tell you how to use them.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-06', 'skin-hormones', 2, 'Toothpaste is a great spot treatment.', 'myth', 'It was made for teeth.', 'Myth. Toothpaste can irritate and dry your skin. Products made for spots are a better bet.', NULL, 'British Association of Dermatologists: Acne', 'draft', true, now()),
  ('skin-hormones-2-07', 'skin-hormones', 2, 'Taking your make-up off before bed is good for your skin.', 'fact', 'Pores need a break overnight.', 'True. Make-up left on overnight can clog pores.', 'Washing make-up brushes regularly helps too.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-2-08', 'skin-hormones', 2, 'A good acne cream clears skin overnight.', 'myth', 'Patience is the secret ingredient.', 'Myth. Most acne treatments take 6 to 8 weeks to show a real difference.', 'Take a photo now so you can see your progress in a couple of months.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-01', 'skin-hormones', 3, 'Deep, painful spots that leave scars are worth seeing a doctor about.', 'fact', 'Some acne needs stronger help.', 'True. Prescription treatments can help prevent scarring.', 'Dermatologists are doctors who specialise in skin.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-02', 'skin-hormones', 3, 'A pharmacist can help with mild spots, no appointment needed.', 'fact', 'You don’t always need a doctor.', 'True. They can recommend creams and gels and tell you when to see a doctor.', 'Benzoyl peroxide is a common pharmacy spot treatment.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-03', 'skin-hormones', 3, 'If acne is getting you down, that alone is a good reason to get help.', 'fact', 'Feelings count too.', 'True. Acne can affect confidence and mood, and you deserve support.', 'Asking for help isn’t vain. Skin health is health.', 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-04', 'skin-hormones', 3, 'Dark marks left by spots are always there for good.', 'myth', 'Marks and scars are different things.', 'Myth. Dark marks usually fade over months. Sun protection helps them fade faster.', 'These dark marks are more common on darker skin tones.', 'British Association of Dermatologists: Acne', 'draft', true, now()),
  ('skin-hormones-3-05', 'skin-hormones', 3, 'Spots plus extra hair on your face or body can be a clue to a hormone condition like PCOS.', 'fact', 'Look at the bigger picture.', 'True. If acne comes with extra hair or irregular periods, a doctor may check for PCOS.', 'PCOS is one of the most common hormone conditions in women.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('skin-hormones-3-06', 'skin-hormones', 3, 'Acne just has to run its course. Nothing really helps.', 'myth', 'Treatment exists.', 'Myth. Acne can be treated, so you don’t have to wait it out.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-07', 'skin-hormones', 3, 'Some stronger acne medicines need regular check-ups.', 'fact', 'Strong medicines need a watchful eye.', 'True. Check-ups make sure the treatment is working safely.', NULL, 'NHS: Acne', 'draft', true, now()),
  ('skin-hormones-3-08', 'skin-hormones', 3, 'Sudden bad acne as an adult is always down to stress.', 'myth', 'There can be other causes.', 'Myth. Stress can play a part, but hormones and medicines can too. A doctor can help work it out.', 'Some medicines can trigger acne as a side effect.', 'NHS: Acne', 'draft', true, now()),
  ('pcos-1-01', 'pcos', 1, 'PCOS stands for polycystic ovary syndrome.', 'fact', 'Poly means many.', 'True. It’s a common condition that affects how the ovaries work.', 'PCOS was first described by doctors in the 1930s.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-02', 'pcos', 1, 'PCOS is super rare.', 'myth', 'How common do you think it is?', 'Myth. It’s thought to affect about 1 in 10 women. That could be a few people in your class.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-03', 'pcos', 1, 'PCOS means you have dangerous cysts on your ovaries.', 'myth', 'What are those ‘cysts’ really?', 'Myth. They’re small follicles that hold eggs. They aren’t harmful, and not everyone with PCOS has them.', 'Those follicles are eggs that didn’t fully develop.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-04', 'pcos', 1, 'With PCOS, your ovaries might skip releasing an egg some months.', 'fact', 'Think irregular cycles.', 'True. Skipped ovulation is why periods can be irregular with PCOS.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-05', 'pcos', 1, 'PCOS is caused by something you did.', 'myth', 'What does the research say?', 'Myth. The exact cause isn’t known, but it’s linked to hormones and genes, not anything you did.', 'Scientists are still researching exactly what causes PCOS.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-06', 'pcos', 1, 'PCOS can run in families.', 'fact', 'Genes play a part.', 'True. You’re more likely to have it if a close relative does.', 'If your mum or sister has PCOS, it’s worth knowing the signs.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-07', 'pcos', 1, 'PCOS only affects your ovaries.', 'myth', 'Think insulin, skin and mood.', 'Myth. It can also affect insulin, skin, hair and mood.', 'Many people with PCOS have insulin resistance.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-1-08', 'pcos', 1, 'There’s no cure for PCOS, but you can manage it really well.', 'fact', 'Managing is the goal.', 'True. Lifestyle changes and medicines can help with most symptoms.', 'Lots of people with PCOS live full, healthy lives.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-01', 'pcos', 2, 'Irregular or missing periods can be a sign of PCOS.', 'fact', 'Look at your cycle pattern.', 'True. It’s one of the most common signs.', 'Having very few periods a year is a sign worth mentioning to a doctor.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-02', 'pcos', 2, 'Extra hair on the face, chest or back can be linked to PCOS.', 'fact', 'Higher androgens are a clue.', 'True. Higher levels of androgens can cause extra hair growth.', 'Extra hair growth has a medical name: hirsutism.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-03', 'pcos', 2, 'Everyone with PCOS has exactly the same symptoms.', 'myth', 'PCOS looks different on everyone.', 'Myth. Some people have lots of symptoms, others only one or two.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-04', 'pcos', 2, 'Thinning hair on your head can be linked to PCOS.', 'fact', 'Androgens affect scalp hair too.', 'True. Some people with PCOS notice thinning or hair loss.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-05', 'pcos', 2, 'One blood test is all it takes to know if you have PCOS.', 'myth', 'Doctors look at several things.', 'Myth. Doctors look at symptoms, blood tests and sometimes an ultrasound scan.', 'An ultrasound scan uses sound waves and doesn’t hurt.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-06', 'pcos', 2, 'Oily skin and stubborn spots can be linked to PCOS.', 'fact', 'Hormones affect skin.', 'True. Higher androgens can make skin oilier and spots more likely.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-07', 'pcos', 2, 'Only people who are overweight get PCOS.', 'myth', 'PCOS shows up in every body type.', 'Myth. People of any weight can have PCOS, though it can make weight gain more likely.', 'PCOS in slimmer people is sometimes called ‘lean PCOS’.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-2-08', 'pcos', 2, 'Dark, velvety skin patches, often on the neck, can be linked to PCOS.', 'fact', 'Look at the neck or armpits.', 'True. They can be a sign the body isn’t using insulin well, which is common in PCOS.', 'This skin change has a medical name: acanthosis nigricans.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-01', 'pcos', 3, 'Moving your body regularly can help manage PCOS.', 'fact', 'Movement helps insulin work.', 'True. Exercise helps your body use insulin better, which can ease symptoms.', 'Mixing cardio with strength exercise can be helpful.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-02', 'pcos', 3, 'There’s one magic diet that cures PCOS.', 'myth', 'Is there a magic menu?', 'Myth. No diet cures PCOS, but balanced eating can help manage it.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-03', 'pcos', 3, 'For people who are overweight, losing even a little weight can ease PCOS.', 'fact', 'Small changes count.', 'True. Losing around 5 percent of body weight can help with periods and other symptoms.', 'For someone weighing 80 kg, 5 percent is just 4 kg.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-04', 'pcos', 3, 'Medicines can help make periods more regular with PCOS.', 'fact', 'Doctors have options.', 'True. A doctor can suggest treatments for periods and other symptoms.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-05', 'pcos', 3, 'Having PCOS means you can never have children.', 'myth', 'What does the evidence say?', 'Myth. Many people with PCOS have children, some with a little help from treatment.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-06', 'pcos', 3, 'PCOS can affect your mood, and support is out there.', 'fact', 'Feelings matter too.', 'True. People with PCOS are more likely to feel anxious or low. Talking to a doctor can help.', 'You’re not alone: PCOS support groups exist online and in many countries.', 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-07', 'pcos', 3, 'Once you’re diagnosed with PCOS, you never need another check-up.', 'myth', 'Long-term health matters.', 'Myth. Regular check-ups help keep an eye on things like blood sugar and blood pressure.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('pcos-3-08', 'pcos', 3, 'Good sleep and less stress are part of looking after PCOS.', 'fact', 'Rest helps hormones.', 'True. Sleep and stress affect hormones and energy.', NULL, 'NHS: Polycystic ovary syndrome', 'draft', true, now()),
  ('food-cycle-1-01', 'food-cycle', 1, 'A mix of different foods helps your body all month long.', 'fact', 'Variety is the spice of life.', 'True. Fruit, veg, wholegrains and protein give your body what it needs.', '‘Eating the rainbow’ is an easy way to get variety.', 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-02', 'food-cycle', 1, 'Skipping meals is a good way to beat bloating.', 'myth', 'Your body needs regular fuel.', 'Myth. Skipping meals can drain your energy and mood. Small, regular meals work better.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-1-03', 'food-cycle', 1, 'Fruit and veg can help keep your tummy happy on your period.', 'fact', 'Think fibre.', 'True. Fibre keeps digestion moving, which can help with period tummy troubles.', 'Oats, beans and whole fruit are great sources of fibre.', 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-04', 'food-cycle', 1, 'Your teens are a key time for building strong bones.', 'fact', 'Think milk, yoghurt and leafy greens.', 'True. Calcium helps build bones, and your teens are when you build a lot of bone strength.', 'Your bones reach their peak strength around age 30.', 'NHS: Calcium', 'draft', true, now()),
  ('food-cycle-1-05', 'food-cycle', 1, 'Wholegrains give you steadier energy than sugary snacks.', 'fact', 'Slow and steady.', 'True. They release energy slowly, so you avoid quick highs and crashes.', 'Brown rice, oats and wholemeal bread are all wholegrains.', 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-06', 'food-cycle', 1, 'You need special ‘period foods’ to stay healthy.', 'myth', 'Everyday food is enough.', 'Myth. No special foods needed. A normal balanced diet supports your cycle.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-1-07', 'food-cycle', 1, 'Drinking enough water still matters on your period.', 'fact', 'Stay topped up.', 'True. Staying hydrated helps your energy and can ease headaches.', 'Water, milk and sugar-free drinks all count towards your fluids.', 'NHS: Water, drinks and your health', 'draft', true, now()),
  ('food-cycle-1-08', 'food-cycle', 1, 'Cutting out whole food groups is a healthy way to fix period symptoms.', 'myth', 'Balance is key.', 'Myth. You could miss out on nutrients. Talk to a doctor or dietitian first.', NULL, 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-2-01', 'food-cycle', 2, 'Iron is what helps your blood carry oxygen around your body.', 'fact', 'It’s part of your red blood cells.', 'True. Iron is needed to make haemoglobin, the oxygen-carrier in red blood cells.', 'Haemoglobin is what makes blood red.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-02', 'food-cycle', 2, 'Heavy periods can leave you low on iron.', 'fact', 'Blood contains iron.', 'True. Losing lots of blood each month can lead to low iron or anaemia.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-03', 'food-cycle', 2, 'Red meat is the only food with iron in it.', 'myth', 'Think plants too.', 'Myth! Beans, lentils, dark leafy greens, nuts and some breakfast cereals have iron too.', 'Iron from plants is absorbed less easily than iron from meat.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-04', 'food-cycle', 2, 'Vitamin C helps your body grab more iron from plant foods.', 'fact', 'Think oranges and peppers.', 'True. Pair iron-rich plants with vitamin C foods to absorb more.', 'A glass of orange juice with fortified cereal is an easy combo.', 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-05', 'food-cycle', 2, 'A cup of tea with your meal can make it harder to absorb iron.', 'fact', 'Timing your cuppa matters.', 'True. Tea and coffee can block some iron, so have them between meals.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-06', 'food-cycle', 2, 'Feeling exhausted all the time is just part of having periods.', 'myth', 'Tiredness can have causes.', 'Myth. Some tiredness is common, but constant exhaustion can mean low iron. Worth checking.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-07', 'food-cycle', 2, 'It’s fine to take iron tablets without checking with anyone.', 'myth', 'Too much iron is a problem too.', 'Myth. Too much iron can be harmful. Ask a doctor or pharmacist first.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-2-08', 'food-cycle', 2, 'Some breakfast cereals have extra iron added.', 'fact', 'Check the label.', 'True. Fortified cereals can be a handy iron boost. Look for iron on the nutrition label.', NULL, 'NHS: Iron deficiency anaemia; NHS: Iron', 'draft', true, now()),
  ('food-cycle-3-01', 'food-cycle', 3, 'Craving snacks before your period is really common.', 'fact', 'You’re not alone.', 'True. Hormone changes can boost your appetite and cravings.', 'Cravings often ease once your period starts.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-02', 'food-cycle', 3, 'A craving always means your body is missing a nutrient.', 'myth', 'Is there proof?', 'Myth. There’s little evidence for that. Cravings are more likely linked to hormones and mood.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-03', 'food-cycle', 3, 'Salty snacks can make bloating worse.', 'fact', 'Salt holds on to water.', 'True. Salt makes your body hang on to water, adding to pre-period bloat.', 'Lots of salt hides in crisps, ready meals and takeaways.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-04', 'food-cycle', 3, 'Small, regular meals can help keep your mood and energy steady.', 'fact', 'Think little and often.', 'True. Eating little and often can help with tiredness and irritability.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-05', 'food-cycle', 3, 'Fizzy drinks help beat the bloat.', 'myth', 'Think about the bubbles.', 'Myth. All those bubbles can add gas and make bloating feel worse.', 'Still water or herbal tea is a gentler choice.', NULL, 'draft', true, now()),
  ('food-cycle-3-06', 'food-cycle', 3, 'Eating chocolate on your period is bad for you.', 'myth', 'Enjoy in balance.', 'Myth. Chocolate is fine as part of a balanced diet. No guilt needed.', 'Dark chocolate even contains a little iron.', 'NHS: Eat well', 'draft', true, now()),
  ('food-cycle-3-07', 'food-cycle', 3, 'Too much caffeine can make you feel more jittery before your period.', 'fact', 'Think coffee and energy drinks.', 'True. Cutting down may help if you feel anxious or can’t sleep before your period.', NULL, 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now()),
  ('food-cycle-3-08', 'food-cycle', 3, 'Pre-period bloating happens because you ate too much.', 'myth', 'Hormones are the main reason.', 'Myth. Hormone changes make your body hold on to water. That’s most of the bloat.', 'Bloating usually eases once your period starts.', 'NHS: Premenstrual syndrome (PMS)', 'draft', true, now())
